import{_ as t,o as e,c as d,a5 as s}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"分布式 ID 生成","description":"订单号、用户 ID、消息 ID，这些标识要全局唯一。单库时代自增主键就够了，拆库分表之后，多台机器各自生成 ID，怎么保证不撞车，还要尽量有序。本章只回答这一个问题。","frontmatter":{},"headers":[],"relativePath":"scenarios/04-data-access/chapter-04-distributed-id.md","filePath":"scenarios/04-data-access/chapter-04-distributed-id.md"}'),i={name:"scenarios/04-data-access/chapter-04-distributed-id.md"};function c(r,a,l,n,o,p){return e(),d("div",null,[...a[0]||(a[0]=[s('<h1 id="分布式-id-生成" tabindex="-1" data-src-line="1" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">分布式 ID 生成 <a class="header-anchor" href="#分布式-id-生成" aria-label="Permalink to &quot;分布式 ID 生成&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><p data-src-line="3" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">订单号、用户 ID、消息 ID，这些标识要全局唯一。单库时代自增主键就够了，拆库分表之后，多台机器各自生成 ID，怎么保证不撞车，还要尽量有序。本章只回答这一个问题。</p></blockquote><h2 id="_1-自增主键为什么失效" tabindex="-1" data-src-line="5" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">1. 自增主键为什么失效 <a class="header-anchor" href="#_1-自增主键为什么失效" aria-label="Permalink to &quot;1. 自增主键为什么失效&quot;">​</a></h2><p data-src-line="7" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">单库时 ID 靠数据库自增，<code>AUTO_INCREMENT</code> 或 <code>GENERATED ALWAYS AS IDENTITY</code>，由数据库保证唯一且递增。拆成多库或多实例后，每个库各自维护自己的自增序列，两个库都会从 1 开始往上加，撞车是必然的。</p><p data-src-line="9" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">于是有了三种主流方案，区别在于唯一性和有序性分别怎么保证。</p><h2 id="_2-uuid" tabindex="-1" data-src-line="11" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">2. UUID <a class="header-anchor" href="#_2-uuid" aria-label="Permalink to &quot;2. UUID&quot;">​</a></h2><p data-src-line="13" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">UUID 用随机数加时间戳拼出 128 位，本地生成，不依赖任何中心节点，绝对唯一。</p><p data-src-line="15" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">它的致命伤是无序。UUID 是随机分布的，用它做主键，数据库 B+ 树每插一条都要在叶子节点随机找位置，页分裂频繁，索引碎片化严重，写入性能随数据量增长明显下降。</p><p data-src-line="17" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">结论是 UUID 适合消息 ID、日志 ID 这类只要求唯一、不要求有序的场景。凡是要落数据库主键、要按时间排序的 ID，别用 UUID。</p><h2 id="_3-雪花算法" tabindex="-1" data-src-line="19" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">3. 雪花算法 <a class="header-anchor" href="#_3-雪花算法" aria-label="Permalink to &quot;3. 雪花算法&quot;">​</a></h2><p data-src-line="21" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">雪花算法把 64 位拆成三段，时间戳、机器标识、序列号。时间戳占高位，保证整体递增；机器标识区分不同节点；序列号处理同一毫秒内的并发。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 1 位符号 | 41 位时间戳（毫秒） | 10 位机器标识 | 12 位序列号 |</span></span></code></pre></div><p data-src-line="27" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">时间戳放高位是关键。生成的 ID 随时间递增，做主键时插入基本都在索引末尾，页分裂少。10 位机器标识支持 1024 台机器，12 位序列号支持同一毫秒 4096 个 ID。</p><p data-src-line="29" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">它有两个绕不开的坑。一是时钟回拨，机器的系统时间被 NTP 往前调，时间戳变小，可能生成重复 ID。处理方式要么抛异常拒绝服务，要么短暂等待时钟追回来。二是机器标识要分配，1024 台机器各自用哪个编号，得有一个配置或注册机制，不能靠机器自己猜。</p><h2 id="_4-号段模式" tabindex="-1" data-src-line="31" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">4. 号段模式 <a class="header-anchor" href="#_4-号段模式" aria-label="Permalink to &quot;4. 号段模式&quot;">​</a></h2><p data-src-line="33" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">号段模式把发号权交回数据库，但不每次取一条，而是一次取一段。数据库里一张表存当前已经发到哪，应用启动时取一段，比如 1 到 1000，本机在这段内自增，用完了再去取下一段。</p><p data-src-line="35" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">它解决了两个问题。一是唯一性，靠数据库的行锁保证各实例拿到的号段不重叠。二是数据库压力，取号段是低频操作，一段能用很久，不像每插一条都依赖数据库自增。</p><p data-src-line="37" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">代价是号段耗尽时机器的本地序列可能乱序，且拿号段这个动作本身依赖数据库，数据库挂了就发不出新 ID。它适合对 ID 只要求趋势递增、不要求严格连续的场景，比如订单号。</p><h2 id="_5-怎么选" tabindex="-1" data-src-line="39" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">5. 怎么选 <a class="header-anchor" href="#_5-怎么选" aria-label="Permalink to &quot;5. 怎么选&quot;">​</a></h2><table tabindex="0"><thead data-src-line="41" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><tr data-src-line="41" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><th style="text-align:left;">方案</th><th style="text-align:left;">唯一性</th><th style="text-align:left;">有序性</th><th style="text-align:left;">依赖</th><th style="text-align:left;">适用</th></tr></thead><tbody data-src-line="43" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><tr data-src-line="43" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><td style="text-align:left;">UUID</td><td style="text-align:left;">本地保证</td><td style="text-align:left;">无序</td><td style="text-align:left;">无</td><td style="text-align:left;">消息、日志 ID</td></tr><tr data-src-line="44" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><td style="text-align:left;">雪花算法</td><td style="text-align:left;">时钟依赖</td><td style="text-align:left;">递增</td><td style="text-align:left;">时钟</td><td style="text-align:left;">订单、用户主键</td></tr><tr data-src-line="45" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md"><td style="text-align:left;">号段模式</td><td style="text-align:left;">数据库保证</td><td style="text-align:left;">趋势递增</td><td style="text-align:left;">数据库</td><td style="text-align:left;">订单号等业务号</td></tr></tbody></table><p data-src-line="47" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">判断只看两个问题，这个 ID 要不要做主键，能不能容忍时钟问题。要主键又不想处理时钟回拨，用雪花算法；要业务号、能接受依赖数据库，用号段模式；只是要个唯一标识，UUID 最简单。</p><p data-src-line="49" data-src-file="scenarios/04-data-access/chapter-04-distributed-id.md">三种方案都不是银弹，共同的底线是，ID 生成逻辑要封装在一个独立的发号服务或工具类里，别散落在业务代码各处。散落之后想换方案，就是一场全量改造。</p>',22)])])}const u=t(i,[["render",c]]);export{f as __pageData,u as default};
